import {diagram,architecture} from './diagrams.js';
import {appendixTabs} from './appendix.js';
import {mainIds,shortened,nextPosition,parsePosition} from './navigation.js';
import {escapeHtml as e,inline,blocks,renderBlock} from './markdown.js';
const {slides,sources,supplemental}=window.SEMINAR;
const stage=document.querySelector('#stage'),overlay=document.querySelector('#overlay');
const params=new URLSearchParams(location.search),presenter=params.has('presenter');
const state={...parsePosition(location.hash,slides),notesOpen:false,reducedMotion:matchMedia('(prefers-reduced-motion: reduce)').matches,appendixReturn:null,selectedComparison:0,appendixPage:0,short:false,demoLinks:{S11:'demo.html?demo=hermes',S21:'demo.html?demo=pydantic'}};
let timer=null,channel,receiving=false;try{channel=new BroadcastChannel('agent-seminar-2');}catch{}
const current=()=>slides.find(s=>s.id===state.slideId);
function fit(){const el=stage.querySelector('.slide');if(el){el.style.position='absolute';el.style.left='50%';el.style.top='50%';el.style.transform=`translate(-50%,-50%) scale(${Math.min(stage.clientWidth/1920,stage.clientHeight/1080)})`;}}
function publish(){const message={slideId:state.slideId,buildStep:state.buildStep,short:state.short};channel?.postMessage(message);try{localStorage.setItem('seminar-position',JSON.stringify(message));}catch{}}
function updateHash(){history.replaceState(null,'',location.pathname+location.search+'#'+state.slideId+'/'+state.buildStep);}
function render(){const s=current();document.body.classList.toggle('reduced',state.reducedMotion);document.querySelector('#motion').textContent=state.reducedMotion?'동작 줄이기: 켬':'동작 줄이기';
 if(presenter){renderPresenter(s);updateHash();if(!receiving)publish();return;}
 const appendix=s.id.startsWith('X');
 const copy=s.onScreen.map((t,i)=>`<p class="reveal ${Math.round(i*(s.buildSteps.length-1)/Math.max(1,s.onScreen.length-1))>state.buildStep?'pending':''}">${e(t)}</p>`).join('');
 const hero=s.id==='S00';
 stage.innerHTML=`<article class="slide ${hero?'hero':''}" aria-label="${s.id} ${e(s.title)}"><div class="eyebrow"><span>AGENT FRAMEWORK <b>/</b> ${e(s.section)}</span><span>SEMINAR 02 · ${s.id}</span></div><h1 class="${s.title.length>34?'long':''}">${e(s.title)}</h1>${hero?`<div class="subtitle">${e(s.onScreen[0])}</div><div class="subtitle reveal ${state.buildStep<1?'pending':''}">${e(s.onScreen[1])}</div><div class="question reveal ${state.buildStep<1?'pending':''}">${e(s.onScreen[2])}</div><div class="techline"><strong>Hermes</strong><span>Claude Code</span><strong>PydanticAI</strong><span>OpenAI Agents SDK</span><span>Claude Agent SDK</span><span>Google ADK</span><span>Microsoft</span></div>`:appendix?'<div id="appendix" class="appendix-content"></div>':`<div class="content"><div class="copy">${copy}${s.id==='S11'||s.id==='S21'?`<p class="status">실제 실행 기록 미연결</p><button data-action="demo">별도 Demo ${s.id==='S11'?'1':'2'} · 설명용 재생</button>`:''}</div><div>${diagram(s,state.buildStep)}</div></div>`}${!hero&&!appendix?'<div class="legend"><span><i class="model"></i>Model</span><span><i></i>Runtime</span><span><i class="tool"></i>Tool</span><span><i class="memory"></i>Context / Store</span></div>':''}<footer><span>${appendix?`부록 ${s.id.slice(1)} / 10`:`${Number(s.id.slice(1))+1} / 41`} · ${e(s.section)}</span><span>${e(s.sourceRefs.split(';')[0]||'C 고정 분석')} · ${e(s.version)}</span><div>${appendix?'<button data-action="return">발표로 돌아가기</button>':s.appendixLinks.map(id=>`<button data-jump="${id}">${id}</button>`).join('')}</div></footer></article>`;
 document.querySelector('#step').textContent=`${state.buildStep+1} / ${s.buildSteps.length} 단계`;
 if(appendix)renderAppendix(s);fit();updateHash();if(!receiving)publish();
}
function renderPresenter(s){const i=mainIds.indexOf(s.id);stage.innerHTML=`<div class="presenter"><div class="eyebrow">발표자 전용 · 청중 화면과 분리 <span id="clock"></span></div><h1>${s.id} ${e(s.title)}</h1><p>단계 ${state.buildStep+1}/${s.buildSteps.length}: ${e(s.buildSteps[state.buildStep])}</p><div class="note">${inline(s.speakerNotes||s.body)}</div><p class="next">다음: ${e(slides.find(x=>x.id===mainIds[i+1])?.title||'마지막 장')}</p><p>${e(s.sourceRefs)} · ${e(s.version)}</p><button data-action="sources">Sources</button> <button data-action="toc">목차</button><p>청중 창과 같은 주소의 발표자 보기를 열면 위치가 동기화됩니다.</p></div>`;stage.style.display='block';stage.style.overflow='auto';document.querySelector('#step').textContent=`${state.buildStep+1}/${s.buildSteps.length}`;}
function appendixBlocks(s){return appendixTabs(s);}
function renderAppendix(s){const parts=appendixBlocks(s);const index=Math.min(state.selectedComparison,parts.length-1),originalBlock=parts[index].block,b=s.id==='X10'&&originalBlock.type==='table'?{...originalBlock,rows:originalBlock.rows.filter(row=>row.join(' ').toLowerCase().includes((state.qaSearch||'').toLowerCase()))}:originalBlock;const container=document.querySelector('#appendix');container.innerHTML=`<div class="appendix-tabs" role="tablist">${parts.map((p,i)=>`<button role="tab" aria-selected="${index===i}" data-tab="${i}">${i+1}. ${e(p.title)}</button>`).join('')}<button data-action="appendix-all">현재 부록 전문</button></div><div class="appendix-view" role="tabpanel"></div>`;
 const view=container.querySelector('.appendix-view');let shown=b;if(b.type==='table'){const pageSize=b.headers.length>4?1:6;const total=Math.max(1,Math.ceil(b.rows.length/pageSize));state.appendixPage=Math.min(state.appendixPage,total-1);const rows=b.rows.slice(state.appendixPage*pageSize,(state.appendixPage+1)*pageSize);shown=b.headers.length>4?{type:'table',headers:['연구 영역: '+rows[0][0],'원문 기호'],rows:b.headers.slice(1).map((name,i)=>[name,rows[0][i+1]])}:{...b,rows};view.innerHTML=renderBlock(shown)+`<div class="pager"><button data-page="-1" ${state.appendixPage===0?'disabled':''}>이전 행</button><span>${state.appendixPage+1} / ${total}</span><button data-page="1" ${state.appendixPage===total-1?'disabled':''}>다음 행</button></div>`;
 if(s.id==='X07')view.innerHTML+='<p class="status">후속 검증 질문 · 테스트 결과 아님</p><button data-action="case-template">선택 사례 분석 틀</button>';
 if(s.id==='X09')view.insertAdjacentHTML('afterbegin','<p class="status">◎ 대표 연구 사례 / ○ 기능·코드 존재 / △ 별도 보완 고려 / — 직접 연구 기준 제한<br>성능 점수·미지원 표가 아닙니다. * 내부 Graph와 별도 사용자 Graph 구분. ** 별도 Tool/Harness/앱 구성 포함.</p>');
 }else view.innerHTML=renderBlock(shown);
 if(s.id==='X10'){view.insertAdjacentHTML('afterbegin','<input id="qa-search" type="search" aria-label="Q&A 검색" placeholder="질문 / 답변 / Q 번호 검색" value="'+e(state.qaSearch||'')+'" style="width:100%;padding:12px;background:#0B1020;color:white;border:1px solid #33415D;margin-bottom:16px">');document.querySelector('#qa-search').oninput=ev=>{state.qaSearch=ev.target.value;state.appendixPage=0;renderAppendix(s);const input=document.querySelector('#qa-search');input.focus();};}
 if(s.id==='X07')view.querySelectorAll('tbody tr').forEach(row=>{const first=row.querySelector('td');const id=first.textContent;first.innerHTML='<button data-case="'+e(id)+'">'+e(id)+'</button>';});
 if(parts[index].architecture)view.insertAdjacentHTML('afterbegin','<div style="height:360px">'+architecture('arch-'+parts[index].architecture,99)+'</div>');
}
function modal(title,html){pause();document.querySelector('#overlay-title').textContent=title;document.querySelector('#overlay-body').innerHTML=html;if(!overlay.open)overlay.showModal();}
function close(){overlay.close();state.notesOpen=false;}
function notes(){state.notesOpen=true;const s=current();modal(`${s.id} 발표자 노트`,`<div class="notes-section">${inline(s.speakerNotes||s.body)}</div><h3>단계 전개</h3>${s.buildSteps.map((x,i)=>`<p>${i+1}. ${e(x)}</p>`).join('')}<h3>그림 제작 기준</h3><p>${inline(s.visual)}</p><h3>출처</h3><p>${e(s.sourceRefs)}</p><button data-action="deep-notes">심층 설명 E</button>`);}
function sourcePanel(){const s=current();modal('Sources · 버전과 근거 범위',`<p>${e(s.sourceRefs)}<br>${e(s.version)}</p><p>SRC 공개 소스 · DOC 공식 계약 · INF 설계 해석 · UNV 추가 확인 · PSEUDO 의사코드</p><p>2026-10-31 분석을 계승합니다. 공식 문서와 고정 버전은 다를 수 있습니다.</p><p><a href="sources/analysis.md" target="_blank">내용 원본 C 전문</a> · <a href="sources/blueprint.md" target="_blank">이번 블루프린트</a> · <a href="sources/design.md" target="_blank">디자인 원본 D</a> · <a href="sources/traceability.md" target="_blank">C 절별 추적표</a></p>${Object.values(sources).map(g=>`<details ${s.section===g.name?'open':''}><summary>${e(g.name)}</summary><div class="sources-list">${g.links.map(l=>`<a href="${e(l.url)}" target="_blank" rel="noopener">${e(l.label)}</a>`).join('')}</div></details>`).join('')}`);}
function toc(){modal('목차 · 본문 41장 / 상세 부록 10장',`<input type="search" id="search" placeholder="제목 또는 S14 / X06 검색" aria-label="목차 검색"><p><button data-action="path">발표 경로: ${state.short?'축약 (36장)':'전체 (41장)'}</button></p><div class="toc-grid">${slides.map(s=>`<button data-jump="${s.id}" data-title="${e(s.title.toLowerCase())}"><b>${s.id}</b>${e(s.title)}</button>`).join('')}</div>`);document.querySelector('#search').addEventListener('input',ev=>{const q=ev.target.value.toLowerCase();document.querySelectorAll('.toc-grid button').forEach(b=>b.hidden=!b.textContent.toLowerCase().includes(q));});}
function jump(id){if(!slides.some(s=>s.id===id))return;if(id.startsWith('X')&&!state.slideId.startsWith('X'))state.appendixReturn={slideId:state.slideId,buildStep:state.buildStep};state.slideId=id;state.buildStep=0;state.selectedComparison=0;state.appendixPage=0;close();pause();render();}
function pause(){clearInterval(timer);timer=null;document.querySelector('#play').textContent='자동 재생';}
function advance(dir){Object.assign(state,nextPosition(state,slides,dir,state.short?shortened:mainIds));render();}
const actions={next:()=>advance(1),prev:()=>advance(-1),reset:()=>{state.buildStep=0;pause();render();},final:()=>{state.buildStep=current().buildSteps.length-1;pause();render();},notes,toc,sources:sourcePanel,close,return:()=>{Object.assign(state,state.appendixReturn||{slideId:'S00',buildStep:0});state.appendixReturn=null;render();},motion:()=>{state.reducedMotion=!state.reducedMotion;pause();render();},play:()=>{if(timer){pause();return;}if(state.reducedMotion){modal('자동 재생','<p>동작 줄이기가 켜져 있습니다. 수동으로 단계를 진행하거나 동작 줄이기를 끈 뒤 재생하세요.</p>');return;}timer=setInterval(()=>{if(state.slideId==='S40'&&state.buildStep===current().buildSteps.length-1){pause();return;}const before=state.slideId+'/'+state.buildStep;advance(1);if(before===state.slideId+'/'+state.buildStep)pause();},4500);document.querySelector('#play').textContent='Pause';},presenter:()=>window.open('index.html?presenter=1#'+state.slideId+'/'+state.buildStep,'seminar-presenter','width=1100,height=850'),fullscreen:()=>{if(document.fullscreenElement)document.exitFullscreen?.();else document.documentElement.requestFullscreen?.();},demo:()=>{try{sessionStorage.setItem('seminar-demo-return',JSON.stringify({slideId:state.slideId,buildStep:state.buildStep}));}catch{}location.href=state.demoLinks[state.slideId]+'&return='+state.slideId+'&step='+state.buildStep;},path:()=>{state.short=!state.short;toc();},'deep-notes':()=>modal('발표자 심층 설명',blocks(supplemental).map(renderBlock).join('')),'appendix-all':()=>modal(current().id+' 전문',appendixTabs(current()).map(t=>'<h3>'+e(t.title)+'</h3>'+renderBlock(t.block)).join('')),'case-template':()=>modal('실패 사례 분석 틀 · 미검증','<p>사례 ID와 상황을 선택하여 다음 항목을 작성합니다.</p><ol><li>입장 / 입력</li><li>최초 검사 코드</li><li>분기</li><li>저장</li><li>재실행 위험</li><li>설계 선택</li></ol><textarea aria-label="사례 분석 메모" rows="9" style="width:100%;font:inherit" placeholder="이 메모는 저장하지 않습니다."></textarea>')};
document.addEventListener('click',ev=>{const b=ev.target.closest('button');if(!b)return;if(b.dataset.action)actions[b.dataset.action]?.();if(b.dataset.case){const row=b.closest('tr');modal(b.dataset.case+' · '+row.children[1].textContent,'<p>'+e(row.children[2].textContent)+'</p><p>입장 → 최초 검사 코드 → 분기 → 저장 → 재실행 위험 → 설계 선택</p><textarea aria-label="사례 분석 메모" rows="9" style="width:100%;font:inherit" placeholder="분석 틀 · 검증 결과 아님 / 저장되지 않음"></textarea>');}if(b.dataset.jump)jump(b.dataset.jump);if(b.dataset.tab){state.selectedComparison=Number(b.dataset.tab);state.appendixPage=0;renderAppendix(current());}if(b.dataset.page){state.appendixPage+=Number(b.dataset.page);renderAppendix(current());}});
document.addEventListener('keydown',ev=>{if(ev.target.closest('input,textarea,select,[contenteditable=true]'))return;if(overlay.open){if(ev.key==='Escape')close();return;}const keys={ArrowRight:'next',' ':'next',ArrowLeft:'prev',n:'notes',N:'notes',r:'reset',R:'reset',t:'toc',T:'toc'};if(keys[ev.key]){ev.preventDefault();pause();actions[keys[ev.key]]();}});
overlay.addEventListener('cancel',()=>{state.notesOpen=false;});window.addEventListener('resize',fit);window.addEventListener('hashchange',()=>{Object.assign(state,parsePosition(location.hash,slides));render();});
function receive(data){if(!data||!slides.some(s=>s.id===data.slideId))return;if(state.slideId===data.slideId&&state.buildStep===data.buildStep&&state.short===data.short)return;receiving=true;Object.assign(state,parsePosition('#'+data.slideId+'/'+data.buildStep,slides),{short:Boolean(data.short)});render();receiving=false;}channel&&(channel.onmessage=ev=>receive(ev.data));window.addEventListener('storage',ev=>{if(ev.key==='seminar-position'){try{receive(JSON.parse(ev.newValue));}catch{}}});
if(presenter){setInterval(()=>{const el=document.querySelector('#clock');if(el)el.textContent=new Date().toLocaleTimeString('ko-KR');},1000);}
render();
